251	    /**
252	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
253	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
254	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
255	     * the sequence of create-time rejections stays readable and a new rule is added as one more
256	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
257	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
258	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
259	     * the household id has been resolved, because that key includes the household id.
260	     *
261	     * @param owner the newly mapped and normalized owner being created
262	     */
263	    private void rejectDisallowedOwnerCreation(Owner owner) {
264	        rejectWhenDailyLimitReached(owner);
265	        rejectWhenCityAtCapacity(owner);
266	    }
267	
268	    /**
269	     * Applies the household-membership rules for a newly normalized owner being created. The
270	     * household id is a deterministic function of the owner's last name and postcode, so owners
271	     * with the same last name and postcode share it automatically; it is assigned to the new owner
272	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
273	     * same last name and postcode is a member of the same household: a second such owner is rejected
274	     * as a household duplicate (409) unless the request declares it shares the household via
275	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
276	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
277	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
278	     * is resolved here before {@link #rejectWhenIdentityInUse}.
279	     *
280	     * @param owner           the newly mapped and normalized owner being created
281	     * @param sharesHousehold whether the request declared that the owner shares an existing household
282	     * @return {@code true} if the owner joined an existing household as a declared member
283	     */
284	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
285	        // Assign the deterministic household id (a pure function of last name and postcode) so every
286	        // owner with the same last name and postcode shares it automatically.
287	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
288	        // Identify any existing owners in the same household (same computed household id).
289	        List<Owner> householdMembers = sameHouseholdOwners(owner);
290	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
291	        // the request declares it shares the household, in which case create it as a declared member.
292	        boolean declaredHouseholdMember = false;
293	        if (!householdMembers.isEmpty()) {
294	            if (!sharesHousehold) {
295	                throw new HouseholdDuplicateException(
296	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
297	            }
298	            declaredHouseholdMember = true;
299	        }
300	        // Record the size of this owner's household after this create, fixed at creation time.
301	        owner.setHouseholdSize(householdMembers.size() + 1);
302	        return declaredHouseholdMember;
303	    }
