305	    /**
306	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
307	     * has already been resolved: the namesake count, the per-city customer code, the membership
308	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
309	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
310	     * here keeps {@link #addOwner} focused on the high-level create sequence.
311	     *
312	     * @param owner the owner being created, already normalized and with its household resolved
313	     */
314	    private void assignDerivedFields(Owner owner) {
315	        // Record how many existing owners already share this owner's first and last name
316	        // (compared case-insensitively) before this create, fixed at creation time.
317	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
318	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
319	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
320	        // time.
321	        owner.setCustomerCode(customerCode(owner));
322	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
323	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
324	        // creation time.
325	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
326	        // Flag the create when more than 80 owners have already been created on this owner's
327	        // (adjusted business-day) registration date, fixed at creation time.
328	        owner.setBulkSignupWarning(
329	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
330	    }
