423	    /**
424	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
425	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
426	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
427	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
428	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
429	     * server's current date. Canonicalising the address here, before the household checks read it,
430	     * ensures duplicate detection and the shared household id both compare the normalized form.
431	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
432	     * duplicate, household and customer-code rules.
433	     *
434	     * @param owner the newly mapped owner to canonicalize
435	     */
436	    private void normalizeOwnerFields(Owner owner) {
437	        // Canonicalize the owner's address fields on create so the address is stored and returned in
438	        // canonical form and every later comparison (household duplicate detection and the shared
439	        // household id) uses it. A value that is blank after normalization is rejected with 400.
440	        normalizeAddressFields(owner);
441	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
442	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
443	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
444	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
445	        // Store the (already syntactically validated) email lower-cased so it is persisted and
446	        // returned in canonical form. A missing email is left untouched.
447	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
448	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
449	        // canonicalization so the comparison sees the lower-cased value.
450	        rejectDisposableEmailDomain(owner.getEmail());
451	        // Validate the optional postcode against the fixed range for the city's region. A postcode
452	        // is checked only when present (it is optional); one out of range for the city's region is
453	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
454	        // value is left unchanged.
455	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
456	        // Reject a supplied registration date that is later than the server's current date with
457	        // 400, before any defaulting or business-day adjustment, so a future date is never
458	        // persisted regardless of how the roll-forward would move it.
459	        rejectFutureRegistrationDate(owner.getRegistrationDate());
460	        // Default the registration date to the server's current date when the client did not
461	        // supply one, then roll the effective date forward to a business day so a Saturday or
462	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
463	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
464	        // date-derived field (such as the membership number's year segment) and the per-day
465	        // create-limit are computed from.
466	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
467	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
468	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
469	    }
470	
471	    /**
472	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
473	     * returned in canonical form. The owner may supply its address in either of two forms and the
474	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
475	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
476	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
477	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
478	     * stored {@code address} is composed from the normalized structured lines when present — the
479	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
480	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
481	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
482	     * here, before the household checks read it, ensures duplicate detection and the shared household
483	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
484	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
485	     *
486	     * @param owner the newly mapped owner whose address is canonicalized
487	     */
488	    private void normalizeAddressFields(Owner owner) {
489	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
490	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
491	            owner.setAddressLine1(line1);
492	            String composed = line1;
493	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
494	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
495	                owner.setAddressLine2(line2);
496	                composed = line1 + " " + line2;
497	            }
498	            owner.setAddress(composed);
499	        }
500	        else {
501	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
502	        }
503	    }
504	
505	    /**
506	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
507	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
508	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
509	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
510	     * domain part is left untouched.
511	     *
512	     * @param email the owner's canonicalized email, or {@code null} when absent
513	     */
514	    private void rejectDisposableEmailDomain(String email) {
515	        if (email == null) {
516	            return;
517	        }
518	        int at = email.lastIndexOf('@');
519	        if (at < 0) {
520	            return;
521	        }
522	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
523	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
524	            throw new DisposableEmailException(
525	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
526	        }
527	    }
528	
529	    /**
530	     * Rejects a supplied registration date that is later than the server's current date with a
531	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
532	     * accepted, and a date on or before today is left for the normal defaulting and business-day
533	     * adjustment.
534	     *
535	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
536	     */
537	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
538	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
539	            throw new InvalidRegistrationDateException(
540	                "The supplied registration date " + registrationDate + " is later than the current date");
541	        }
542	    }
543	
544	    /**
545	     * The fixed list of public holidays. A registration date that lands on one of these dates is
546	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
547	     */
548	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
549	        java.time.LocalDate.of(2026, 1, 1),
550	        java.time.LocalDate.of(2026, 1, 26),
551	        java.time.LocalDate.of(2026, 4, 25),
552	        java.time.LocalDate.of(2026, 12, 25),
553	        java.time.LocalDate.of(2026, 12, 28));
554	
555	    /**
556	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
557	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
558	     * unchanged. Applied to the effective registration date (whether supplied in the request or
559	     * defaulted to the server date) so the persisted registration date, every value derived from it
560	     * and the per-day create-limit all use the adjusted business day.
561	     *
562	     * @param date the effective registration date
563	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
564	     */
565	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
566	        java.time.LocalDate adjusted = date;
567	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
568	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
569	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
570	            adjusted = adjusted.plusDays(1);
571	        }
572	        return adjusted;
573	    }
574	
575	    /**
576	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
577	     * region derived from the owner's postcode (falling back to the city, via
578	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
579	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
580	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
581	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
582	     * distinct customer codes.
583	     *
584	     * @param owner the owner being created, already normalized
585	     * @return the formatted, de-duplicated customer code
586	     */
587	    private String customerCode(Owner owner) {
588	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
589	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
590	        String base = region + "-" + hash8;
591	        Set<String> taken = existingOwners()
592	            .map(Owner::getCustomerCode)
593	            .filter(code -> code != null)
594	            .collect(Collectors.toSet());
595	        if (!taken.contains(base)) {
596	            return base;
597	        }
598	        int n = 2;
599	        while (taken.contains(base + "-" + n)) {
600	            n++;
601	        }
602	        return base + "-" + n;
603	    }
604	
605	    /**
606	     * Streams the existing owners that the create-time rules match a new owner against. Every
607	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
608	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
609	     * own matching criterion rather than on how the existing owners are retrieved.
610	     *
611	     * @return a stream over all existing owners
612	     */
613	    private Stream<Owner> existingOwners() {
614	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
615	        // new create, so the duplicate, identity and household checks (and the other create-time
616	        // scans built on this helper) ignore it.
617	        return this.clinicService.findAllOwners().stream()
618	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
619	    }
620	
621	    /**
622	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
623	     * fix the per-city sequence of an owner's customer code at creation time.
624	     *
625	     * @param city the city of the owner being created
626	     * @return the number of existing owners in a matching city
627	     */
628	    private int countOwnersInCity(String city) {
629	        return (int) existingOwners()
630	            .filter(existing -> existing.getCity() != null
631	                && existing.getCity().equalsIgnoreCase(city))
632	            .count();
633	    }
634	
635	    /**
636	     * Counts the existing owners whose registration date is the given adjusted business day. Used
637	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
638	     * owners already carry that business day as their registration date.
639	     *
640	     * @param date the adjusted business-day registration date to match
641	     * @return the number of existing owners registered on that date
642	     */
643	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
644	        return (int) existingOwners()
645	            .filter(existing -> date.equals(existing.getRegistrationDate()))
646	            .count();
647	    }
648	
649	    /**
650	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
651	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
652	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
653	     * after 1 July carries the following calendar year's fiscal year.
654	     *
655	     * @param customerCode     the owner's customer code
656	     * @param registrationDate the owner's registration date
657	     * @return the formatted membership number
658	     */
659	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
660	        return String.format("%s-M%02d",
661	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
662	    }
663	
664	    /**
665	     * Returns the existing owners in the given owner's household, i.e. those sharing its
666	     * deterministic household id (the same last name and postcode). The id is computed via
667	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
668	     * whitespace are treated as the same household. Centralising how "the same household" is matched
669	     * here keeps that definition in one place for every caller.
670	     *
671	     * @param owner the owner being created, with its household id already assigned
672	     * @return the existing owners in the owner's household (possibly empty)
673	     */
674	    private List<Owner> sameHouseholdOwners(Owner owner) {
675	        String householdId = owner.getHouseholdId();
676	        return existingOwners()
677	            .filter(existing -> householdId.equals(
678	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
679	            .toList();
680	    }
681	
682	    /**
683	     * Counts the existing owners who share the given first and last name, compared
684	     * case-insensitively. Used to fix an owner's namesake count at creation time.
685	     *
686	     * @param firstName the first name of the owner being created
687	     * @param lastName  the last name of the owner being created
688	     * @return the number of existing owners with a matching first and last name
689	     */
690	    private int countNamesakes(String firstName, String lastName) {
691	        return (int) existingOwners()
692	            .filter(existing -> existing.getFirstName() != null
693	                && existing.getFirstName().equalsIgnoreCase(firstName)
694	                && existing.getLastName() != null
695	                && existing.getLastName().equalsIgnoreCase(lastName))
696	            .count();
697	    }
698	
699	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
700	    @Override
701	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
702	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
703	        if (currentOwner == null) {
704	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
705	        }
706	        currentOwner.setAddress(ownerFieldsDto.getAddress());
707	        currentOwner.setCity(ownerFieldsDto.getCity());
708	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
709	        currentOwner.setLastName(ownerFieldsDto.getLastName());
710	        // Normalize the telephone to canonical E.164 form so it is stored and returned
711	        // consistently with create; an unformattable value is rejected with 400.
712	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
713	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
714	        this.clinicService.saveOwner(currentOwner);
715	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
716	    }
717	
718	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
719	    @Transactional
720	    @Override
721	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
722	        Owner owner = this.clinicService.findOwnerById(ownerId);
723	        if (owner == null) {
724	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
725	        }
726	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
727	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
728	        // duplicate and identity checks (see existingOwners()).
729	        owner.setDeleted(true);
730	        this.clinicService.saveOwner(owner);
731	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
732	    }
733	
734	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
735	    @Override
736	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
737	        Owner owner = this.clinicService.findOwnerById(ownerId);
738	        if (owner == null) {
739	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
740	        }
741	        HttpHeaders headers = new HttpHeaders();
742	        Pet pet = petMapper.toPet(petFieldsDto);
743	        owner.setId(ownerId);
744	        pet.setOwner(owner);
745	        pet.getType().setName(null);
746	        this.clinicService.savePet(pet);
747	        PetDto petDto = petMapper.toPetDto(pet);
748	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
749	            .buildAndExpand(pet.getId()).toUri());
750	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
751	    }
752	
753	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
754	    @Override
755	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
756	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
757	        if (currentOwner != null) {
758	            Pet currentPet = this.clinicService.findPetById(petId);
759	            if (currentPet != null) {
760	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
761	                currentPet.setName(petFieldsDto.getName());
762	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
763	                this.clinicService.savePet(currentPet);
764	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
765	            }
766	        }
767	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
768	    }
769	
770	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
771	    @Override
772	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
773	        HttpHeaders headers = new HttpHeaders();
774	        Visit visit = visitMapper.toVisit(visitFieldsDto);
775	        Pet pet = new Pet();
776	        pet.setId(petId);
777	        visit.setPet(pet);
778	        this.clinicService.saveVisit(visit);
779	        VisitDto visitDto = visitMapper.toVisitDto(visit);
780	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
781	            .buildAndExpand(visit.getId()).toUri());
782	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
783	    }
784	
785	
786	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
787	    @Override
788	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
789	        Owner owner = this.clinicService.findOwnerById(ownerId);
790	        if (owner != null) {
791	            Pet pet = owner.getPet(petId);
792	            if (pet != null) {
793	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
794	            }
795	        }
796	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
797	    }
798	}
